(()=>{const H=window.HBSTV,esc=escapeHtml,storageKey='hbstv-maintenance-v1';let draft;try{draft=JSON.parse(localStorage.getItem(storageKey)||'{}');}catch{draft={};}if(!Array.isArray(draft.events)||!Array.isArray(draft.aliases))draft={schemaVersion:1,events:[],aliases:[]};
const save=()=>{localStorage.setItem(storageKey,JSON.stringify(draft));};
function status(text){document.querySelector('#maintenance-status').textContent=text;}
window.renderMaintenance=screen=>{screen.innerHTML=`<header class="hub-header"><span class="eyebrow">HBSTV · MANUTENÇÃO</span><h2>Organizar os registros.</h2><p>Prepare correções, revise os nomes e exporte o arquivo para publicação.</p></header><div class="hub-note"><strong>Rascunhos neste navegador</strong><p>Salvar aqui mantém a correção neste dispositivo. A base pública só muda quando o arquivo exportado é incorporado e uma nova versão do site é publicada.</p></div><div class="maintenance-actions"><button class="hub-button" data-maintenance-export>Exportar correções (${draft.events.length+draft.aliases.length})</button><label class="hub-button">Importar rascunho<input id="maintenance-import" type="file" accept="application/json,.json"></label></div><p id="maintenance-status" role="status" aria-live="polite"></p><form id="maintenance-event-form" class="hub-form"><h3>Campeonato</h3><label>Registro<select id="maintenance-event"><option value="">Novo campeonato</option>${H.db.events.map(e=>`<option value="${esc(e.id)}">${e.year} · ${esc(e.title)}</option>`).join('')}</select></label><div class="hub-filters"><label>Nome do campeonato<input id="maintenance-title" required maxlength="160" placeholder="TSL | Nome da edição"></label><label>Ano<input id="maintenance-year" type="number" min="2017" max="2100" required></label><label>Organizadora<input id="maintenance-org" required maxlength="60"></label></div><label>Campeão<select id="maintenance-winner"><option value="">Sem registro</option>${H.db.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label>Escalação campeã<textarea id="maintenance-roster" placeholder="Um nick por linha"></textarea></label><div class="hub-filters"><label>MVPs<textarea id="maintenance-mvps" placeholder="Um nick por linha"></textarea></label><label>EVPs<textarea id="maintenance-evps" placeholder="Um nick por linha"></textarea></label></div><label class="hub-check"><input id="maintenance-major" type="checkbox"> Major</label><label>Fonte ou justificativa<textarea id="maintenance-note" required placeholder="Explique a correção e indique a fonte"></textarea></label><button class="hub-button" type="submit">Salvar rascunho do campeonato</button></form><form id="maintenance-alias-form" class="hub-form"><h3>Nome alternativo de jogador</h3><label>Nome antigo ou variação<input id="maintenance-alias" required maxlength="60"></label><label>Jogador correto<select id="maintenance-player">${H.db.players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><button class="hub-button" type="submit">Salvar nome alternativo</button></form><section class="hub-section"><h3>Correções preparadas</h3><div id="maintenance-drafts"></div></section>`;renderDrafts();};
function renderDrafts(){const box=document.querySelector('#maintenance-drafts');if(box)box.innerHTML=draft.events.map(e=>`<div class="hub-draft"><strong>${e.year} · ${esc(e.title)}</strong><span>${e.roster.length} jogadores · ${e.mvps.length} MVPs · ${e.evps.length} EVPs</span><button type="button" data-remove-draft="${esc(e.id)}">Remover rascunho</button></div>`).join('')+draft.aliases.map(a=>`<p>${esc(a.alias)} → ${esc(H.name(a.playerId))}</p>`).join('')||'<p>Nenhuma correção preparada.</p>';const b=document.querySelector('[data-maintenance-export]');if(b)b.textContent='Exportar correções ('+(draft.events.length+draft.aliases.length)+')';}
document.addEventListener('change',async e=>{if(e.target.id==='maintenance-event'){const r=draft.events.find(r=>r.id===e.target.value)||H.event(e.target.value);for(const [id,value] of Object.entries({title:r?.title||'',year:r?.year||'',org:r?.organizer||'',winner:r?.winners[0]||'',roster:r?.roster.map(H.name).join('\n')||'',mvps:r?.mvps.map(H.name).join('\n')||'',evps:r?.evps.map(H.name).join('\n')||'',note:r?.notes?.join('\n')||''}))document.querySelector('#maintenance-'+id).value=value;document.querySelector('#maintenance-major').checked=r?.major||false;}if(e.target.id==='maintenance-import'){try{const value=JSON.parse(await e.target.files[0].text());if(value.schemaVersion!==1||!Array.isArray(value.events)||!Array.isArray(value.aliases))throw Error('Formato de rascunho inválido.');if(value.events.length>500||value.aliases.length>500)throw Error('Arquivo grande demais.');for(const r of value.events){if(typeof r.id!=='string'||typeof r.title!=='string'||!Array.isArray(r.roster)||!Array.isArray(r.mvps)||!Array.isArray(r.evps)||!Array.isArray(r.winners)||!Number.isInteger(r.year)||!Array.isArray(r.notes))throw Error('Registro de campeonato inválido.');for(const id of [...r.roster,...r.mvps,...r.evps])if(!H.person(id))throw Error('Jogador não encontrado: '+id);}for(const a of value.aliases)if(typeof a.alias!=='string'||!H.person(a.playerId))throw Error('Nome alternativo inválido.');draft=value;save();renderDrafts();status('Rascunho importado neste navegador.');}catch(err){status('Não foi possível importar: '+err.message);}}});
document.addEventListener('submit',e=>{if(e.target.id==='maintenance-event-form'){e.preventDefault();try{const val=id=>document.querySelector('#maintenance-'+id).value.trim(),resolve=id=>{const names=val(id).split(/[\n,]+/).map(s=>s.trim()).filter(Boolean),ids=names.map(n=>{const p=H.person(n);if(!p)throw Error('Jogador não encontrado: '+n+'. Cadastre ou confirme o nick antes de vincular.');return p.id;});return [...new Set(ids)];};const id=val('event')||'manual:'+H.key(val('title'))+':'+val('year');const r={id,title:val('title'),year:Number(val('year')),organizer:val('org'),winners:val('winner')?[val('winner')]:[],roster:resolve('roster'),mvps:resolve('mvps'),evps:resolve('evps'),major:document.querySelector('#maintenance-major').checked,notes:[val('note')],sources:['owner-confirmed'],images:H.event(id)?.images||[]};draft.events=draft.events.filter(e=>e.id!==id);draft.events.push(r);save();renderDrafts();status('Campeonato salvo no rascunho local. Exporte as correções para publicar.');}catch(err){status(err.message);}}if(e.target.id==='maintenance-alias-form'){e.preventDefault();const alias=document.querySelector('#maintenance-alias').value.trim(),playerId=document.querySelector('#maintenance-player').value,existing=H.person(alias);if(existing&&existing.id!==playerId){status('Esse nome já identifica outro jogador. A união dos históricos precisa ser conferida antes de publicar.');return;}draft.aliases=draft.aliases.filter(a=>a.alias!==alias);draft.aliases.push({alias,playerId});save();renderDrafts();status('Nome alternativo salvo no rascunho local.');}});
document.addEventListener('click',e=>{if(e.target.closest('[data-maintenance-export]')){const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='hbstv-correcoes.json';a.click();URL.revokeObjectURL(url);status('Arquivo exportado. Ele contém apenas as correções preparadas.');}const b=e.target.closest('[data-remove-draft]');if(b){draft.events=draft.events.filter(r=>r.id!==b.dataset.removeDraft);save();renderDrafts();status('Rascunho removido. A base publicada permanece disponível.');}});
})();
